<script setup lang="ts">
import {apiError} from './apiError';
import {ref,watch} from 'vue';
const props=defineProps<{source:any;projectId:string}>();
const settings=ref({samples:10,seed:42,resource:'grid_channel',rated_kw:4000,rate_per_hour:.02,repair_hours:6});
const batches=ref<any[]>([]);const selected=ref<any>(null);const busy=ref(false);const error=ref('');
const labels:Record<string,string>={samples:'样本数 / 2–20',seed:'起始随机种子',rated_kw:'资源容量上限 / kW',rate_per_hour:'每小时失效率 λ',repair_hours:'修复时长 / h'};
async function refresh(){const response=await fetch('/api/random-balance?project_id='+props.projectId);if(!response.ok)throw Error('读取随机平衡档案失败');batches.value=await response.json()}
watch(()=>props.projectId,()=>{selected.value=null;refresh().catch(e=>error.value=String(e))},{immediate:true});
async function run(){busy.value=true;error.value='';selected.value=null;const project=props.projectId;try{const response=await fetch('/api/random-balance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_run_id:props.source.id,...settings.value})});const data=await response.json();if(!response.ok)throw Error(apiError(data.detail));if(project===props.projectId){selected.value=data;await refresh()}}catch(e){error.value=String(e)}finally{busy.value=false}}
</script>
<template><article><h3>随机生产模拟 / 连续故障样本</h3><p>以当前已计算结果为基准，固定源荷和运行阶段，仅随机抽样一种资源的故障与修复。支持汇总或IEEE33网络模型、2–168小时、2–20个等权样本。</p><p v-if="!source">请先完成单轨迹平衡计算。</p><p v-else>基准 {{source.id.slice(0,8)}}。{{source.scenario_id?'基准已绑定故障场景，需解除场景并重新计算后生成多样本。':''}}</p><div class="grid"><label v-for="(label,key) in labels" class="field">{{label}}<input type="number" min="0" step="any" v-model.number="settings[key as keyof typeof settings]" :disabled="busy"></label><label class="field">抽样资源<select v-model="settings.resource" :disabled="busy"><option value="grid_channel">上级电网</option><option value="transformer">变压器</option><option value="storage">储能功率</option><option value="emergency_gen">应急发电</option><option value="renewable">风光合计</option></select></label></div><button @click="run" :disabled="busy||!source||!!source.scenario_id">{{busy?'正在生成样本并逐条计算…':'执行随机平衡并归档'}}</button><p class="error" v-if="error">{{error}}</p><h3>已保存随机平衡批次</h3><button v-for="batch in batches" class="record" @click="selected=batch">{{batch.created}} · {{batch.summary.sample_count}}个样本 · {{batch.id.slice(0,8)}}</button><template v-if="selected"><p>{{selected.scope}}</p><div class="metrics"><article>发生缺供的样本比例<strong>{{(selected.summary.shortage_sample_probability*100).toFixed(1)}}%</strong></article><article>平均缺供电量<strong>{{selected.summary.mean_energy_deficit_kwh.toFixed(2)}} kWh</strong></article><article>缺供电量P95<strong>{{selected.summary.p95_energy_deficit_kwh.toFixed(2)}} kWh</strong></article></div><p>缺供样本比例的Wilson 95%区间：[{{(selected.summary.shortage_probability_wilson95_lower*100).toFixed(1)}}%，{{(selected.summary.shortage_probability_wilson95_upper*100).toFixed(1)}}%]。这是固定源荷与指定失效率下的条件模拟结果。</p><p v-if="selected.model==='case33'">全部样本最低交流电压 {{selected.summary.ac_min_voltage_pu.toFixed(4)}} pu；平均电压越限时长 {{selected.summary.mean_voltage_violation_hours.toFixed(2)}} h；平均网损电量 {{selected.summary.mean_line_loss_energy_kwh.toFixed(2)}} kWh。仅校核根节点连通区域。</p><h3>分阶段样本统计</h3><table><tr><th>阶段</th><th>发生缺供的样本比例</th><th>平均缺供时段占比</th><th>平均缺供电量 / MWh</th></tr><tr v-for="phase in selected.phase_summary"><td>{{phase.stage}}</td><td>{{(phase.shortage_sample_probability*100).toFixed(1)}}%</td><td>{{phase.mean_shortage_hour_pct.toFixed(1)}}%</td><td>{{phase.mean_energy_deficit_mwh.toFixed(3)}}</td></tr></table><h3>样本明细</h3><div class="scroll"><table><tr><th>样本</th><th>种子</th><th>故障次数</th><th>缺供电量 / kWh</th><th v-if="selected.model==='case33'">最低交流电压 / pu</th><th v-if="selected.model==='case33'">电压越限 / h</th><th>计算报告</th></tr><tr v-for="sample in selected.samples"><td>{{sample.sample}}</td><td>{{sample.seed}}</td><td>{{sample.failure_events}}</td><td>{{sample.expected_energy_deficit_kwh.toFixed(2)}}</td><td v-if="selected.model==='case33'">{{sample.ac_min_voltage_pu.toFixed(4)}}</td><td v-if="selected.model==='case33'">{{sample.voltage_violation_hours}}</td><td><a :href="'/api/runs/'+sample.run_id+'/report'">报告</a></td></tr></table></div><a :href="'/api/random-balance/'+selected.id+'/csv'">导出样本统计CSV</a><details><summary>查看抽样参数</summary><pre>{{JSON.stringify(selected.parameters,null,2)}}</pre></details></template></article></template>
